// === Tab: ParticleNetwork ===
//network
var distThreshold = 100;

//particles
var numOfParticles = 200;
var particles = [];

//containment
var circleRadius = 400;

//interactivity
var gravity = 0;
var mouseWheelSensitivity = 0.001;

var dampeningForce = 0;
var maxDampening = 0.1;

function setup() {
    createCanvas(900, 900);

    //create all the particles
    for (var i = 0; i < numOfParticles; i++) {
        particles.push(new Particle());
    }
}

function draw() {
    background(255);

    //draw background circle
    fill(0);
    noStroke()
    ellipse(width / 2, height / 2, circleRadius * 2);

    //update and show all teh particles
    for (var i = 0; i < particles.length; i++) {
        particles[i].update();
        particles[i].connectNearestParticles(particles, i);
        particles[i].show();
    }
}

function Reset() {
    //reste gravity
    gravity = 0;

    //create new particles
    particles = [];
    for (var i = 0; i < numOfParticles; i++) {
        particles.push(new Particle());
    }
}

function mouseWheel(event) {
    //change gravity
    gravity -= event.delta * mouseWheelSensitivity;
}

function mouseClicked() {
    //reset gravity
    gravity = 0;
}

function mousePressed() {
    //enamble dampening
    if (mouseButton == CENTER) {
        dampeningForce = maxDampening;
    }
}

function mouseReleased() {
    //Disable dampening
    dampeningForce = 0;
}

function keyReleased() {
    //reset
    if (key == ' ') {
        Reset();
    }
}

// === Tab: Particle ===
function Particle() {
    //calculate random spawn vector inide circle
    const vectorInCircle = createVector(random(-1, 1), random(-1, 1));
    vectorInCircle.limit(1);
    vectorInCircle.mult(circleRadius);
    this.pos = createVector(width / 2, height / 2).add(vectorInCircle);

    //calculate random color
    this.color = color(random(255), random(255), random(255));

    //set size
    this.size = 3;

    //create random motion vector
    this.vel = createVector(random(-1, 1), random(-1, 1));

    //array of particles connected with this particle
    this.connectedWith = [];

    //alpha value of the triangles between the particles
    this.triangleAlpha = 100;
}

Particle.prototype.show = function () {
    //darw particle
    fill(this.color);
    noStroke();
    ellipse(this.pos.x, this.pos.y, this.size);

    //darw triangles between particles (only of there are at least two particles connected to this one)
    if (this.connectedWith.length > 1) {
        for (var i = 0; i < this.connectedWith.length - 1; i += 2) { //go through all connected particles in steps of two

            //calculate teh color of the triangle from the particle colors
            var r = (red(this.color) + red(this.connectedWith[i].color) + red(this.connectedWith[i + 1].color)) / 3;
            var g = (green(this.color) + green(this.connectedWith[i].color) + green(this.connectedWith[i + 1].color)) / 3;
            var b = (blue(this.color) + blue(this.connectedWith[i].color) + blue(this.connectedWith[i + 1].color)) / 3;
            var col = color(r, g, b, this.triangleAlpha);

            //darw the shape
            fill(col);
            noStroke();
            beginShape(TRIANGLES);
            vertex(this.pos.x, this.pos.y);
            vertex(this.connectedWith[i].pos.x, this.connectedWith[i].pos.y);
            vertex(this.connectedWith[i + 1].pos.x, this.connectedWith[i + 1].pos.y);
            endShape(CLOSE);
        }
    }
}

Particle.prototype.update = function () {
    //add gravity
    this.vel.add(createVector(0, gravity));

    //add dampening
    var dampening = this.vel.copy().mult(-1);
    dampening.limit(1);
    dampening.mult(dampeningForce);
    this.vel.add(dampening);

    //update position
    this.pos.add(this.vel);

    //calc dist to center for collision
    var center = createVector(width / 2, height / 2);
    var distToCenter = this.pos.dist(center);

    //if particle is leaving circle, pop it back in and reverse its velocity
    if (distToCenter > circleRadius) {
        const vecToCenter = center.copy().sub(this.pos).normalize();

        this.vel = this.vel.sub(vecToCenter.copy().mult(p5.Vector.dot(this.vel, vecToCenter)*2));
        this.pos = center.copy().add(vecToCenter.mult(-circleRadius));
    }
}

Particle.prototype.connectNearestParticles = function (particles, ownIndex) {
    for (var i = 0; i < particles.length; i++) { //go through all particles
        if (i != ownIndex) { //make sure we don't check ourselfs
            //calc dist to the particle
            var dist = this.pos.dist(particles[i].pos);

            //check if we are allready connected to this particle
            var allreadyConnected = false;
            for (var j = 0; j < this.connectedWith.length; j++) {
                if (this.connectedWith[j] == particles[i]) {
                    //after we know we are connected with this particle, check wether we should disconnect
                    if (dist > distThreshold) {
                        this.connectedWith.splice(j, 1);
                    }
                    allreadyConnected = true;
                }
            }

            //only if we arent allready connected to the particle or not just disconnected, check wether we should connect
            if (!allreadyConnected) {
                if (dist < distThreshold) {
                    this.connectedWith.push(particles[i]);
                }
            }
        }
    }
};

